param([string]$RepoRoot)
$ErrorActionPreference="Stop";Set-StrictMode -Version Latest;$Package=$PSScriptRoot;if([string]::IsNullOrWhiteSpace($RepoRoot)){$RepoRoot=Split-Path -Parent $Package};$RepoRoot=(Resolve-Path $RepoRoot).Path;$Payload=Join-Path $Package "Payload";if(@(git -C $RepoRoot status --short -- .\WildsEngine.Core).Count){throw "Core changed"};Get-ChildItem $Payload -Recurse -File|%{$rel=$_.FullName.Substring($Payload.Length).TrimStart('\','/');$dest=Join-Path $RepoRoot $rel;New-Item -ItemType Directory -Path (Split-Path -Parent $dest) -Force|Out-Null;Copy-Item $_.FullName $dest -Force;Write-Host "[INSTALL] $rel" -ForegroundColor Green};dotnet build (Join-Path $RepoRoot "WildsEngine.Core.Tests\WildsEngine.Core.Tests.csproj") -c Release;if($LASTEXITCODE){throw "Build failed"}
